-- Products split: `line`, `edition` and the digital-product fields for the
-- Payload `products` collection (branch hungry-hawking-762203).
--
-- APPLIED to production 2026-10-31 on the owner's approval. Generated by the read-only dry run in
-- sim/products-ddl.sim.test.mjs: drizzle-kit's own statements for this
-- checkout's schema against the live database. It reported
-- hasDataLoss=false, no DROP, and nothing outside `products`.
--
-- Deliberately left out: nine numeric-default SET DEFAULT no-ops, and four
-- `ALTER TABLE "projects_*" DISABLE ROW LEVEL SECURITY` statements (projects_tags,
-- projects_story_chapters, projects_story_results, projects_story_stack).
-- The live ensure_rls event trigger turns RLS on for every new table, so
-- drizzle wants it off where the database has it on. Disabling RLS is never
-- wanted. For the same reason the new `products_audience` table gets an
-- explicit ENABLE ROW LEVEL SECURITY below (the trigger would do it anyway;
-- stating it keeps this file honest).
--
-- Run ONCE, by the owner, in the Supabase SQL editor, BEFORE this branch
-- reaches main. Everything is in one transaction and rolls back whole if any
-- statement fails. Re-running the whole file fails at CREATE TYPE (that is
-- the guard); the backfill statements alone are safe to repeat.
--
-- After running, until the branch is on main: no `pnpm dev` or `pnpm sim`
-- from main or any older checkout. Their schema push would drop these
-- columns and the table without asking.

BEGIN;

CREATE TYPE "public"."enum_products_audience" AS ENUM('founders', 'developers');
CREATE TYPE "public"."enum_products_line" AS ENUM('warekit', 'digital');
CREATE TYPE "public"."enum_products_edition" AS ENUM('netsuite', 'standard');
CREATE TYPE "public"."enum_products_digital_format" AS ENUM('pdf-guide', 'checklist');
CREATE TABLE "products_audience" (
	"order" integer NOT NULL,
	"parent_id" integer NOT NULL,
	"value" "enum_products_audience",
	"id" serial PRIMARY KEY NOT NULL
);
ALTER TABLE products_audience ENABLE ROW LEVEL SECURITY;
ALTER TABLE "products" ADD COLUMN "line" "enum_products_line";
ALTER TABLE "products" ADD COLUMN "edition" "enum_products_edition";
ALTER TABLE "products" ADD COLUMN "digital_format" "enum_products_digital_format";
ALTER TABLE "products" ADD COLUMN "page_count" numeric;
ALTER TABLE "products_audience" ADD CONSTRAINT "products_audience_parent_fk" FOREIGN KEY ("parent_id") REFERENCES "public"."products"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "products_audience_order_idx" ON "products_audience" USING btree ("order");
CREATE INDEX "products_audience_parent_idx" ON "products_audience" USING btree ("parent_id");

-- Backfill. The NetSuite kits, the base `warekit` row, then the digital
-- product and its audience.
UPDATE products SET line = 'warekit', edition = 'netsuite'
 WHERE slug LIKE 'warekit-%-netsuite-%';
UPDATE products SET line = 'warekit' WHERE slug = 'warekit';
UPDATE products SET line = 'digital', digital_format = 'pdf-guide', page_count = 16
 WHERE slug = 'switch-clone-quick-key-rotation-guide';

-- products_audience rows: "order" is 1-based (Payload orders hasMany selects from 1). The
-- NOT EXISTS guard makes this safe to repeat.
INSERT INTO products_audience ("order", parent_id, value)
SELECT v.ord, p.id, v.val::enum_products_audience
  FROM products p
  CROSS JOIN (VALUES (1, 'founders'), (2, 'developers')) AS v(ord, val)
 WHERE p.slug = 'switch-clone-quick-key-rotation-guide'
   AND NOT EXISTS (SELECT 1 FROM products_audience a WHERE a.parent_id = p.id);

COMMIT;
